import { DESKTOP_PREFIX, DESKTOP_START_PREFIX, TABLET_PREFIX, MOBILE_PREFIX, TABLET_START_PREFIX, MOBILE_START_PREFIX } from "./constants";
export const convertStateToClasses = (gridState) => {
    const { lg, md, sm, lgStart, mdStart, smStart } = gridState;
    const classes = [];
    if (lg) {
        classes.push(`${DESKTOP_PREFIX}${lg}`);
    }
    if (md) {
        classes.push(`${TABLET_PREFIX}${md}`);
    }
    if (sm) {
        classes.push(`${MOBILE_PREFIX}${sm}`);
    }
    if (lgStart) {
        classes.push(`${DESKTOP_START_PREFIX}${lgStart}`);
    }
    if (mdStart) {
        classes.push(`${TABLET_START_PREFIX}${mdStart}`);
    }
    if (smStart) {
        classes.push(`${MOBILE_START_PREFIX}${smStart}`);
    }
    return classes;
};
